import {_electron as electron} from 'playwright';import {mkdtemp} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import assert from 'node:assert/strict';
const data=await mkdtemp(path.join(os.tmpdir(),'nodus-onboarding-')),evidence=await mkdtemp(path.join(process.env.RUNNER_TEMP,'nodus-onboarding-evidence-'));const app=await electron.launch({executablePath:process.env.NODUS_QA_EXE,args:[`--user-data-dir=${data}/profile`],env:{...process.env,NODUS_DATA_DIR:data}});
try{const page=await app.firstWindow();await page.locator('#welcomeAccount').waitFor();assert.match(await page.locator('.welcome-storage').innerText(),/保存在本机/);assert(await page.locator('#cloudAccountButton').isVisible());assert(await page.locator('#pluginButton').isHidden());await page.screenshot({path:path.join(evidence,'welcome.png')});
await page.locator('#welcomeConnect').click();assert(await page.locator('#providerInput').isVisible());await page.locator('#closeSettings').click();await page.locator('#welcomeAccount').click();await page.locator('#cloudAuthForm').waitFor();await page.locator('#closeCloud').click();await page.locator('#welcomeDemo').click();await page.locator('#demoDialog').waitFor();await page.locator('#closeDemo').click();
await page.locator('#advancedTools > summary').click();await app.evaluate(({ipcMain})=>{globalThis.pluginNavigations=0;ipcMain.removeHandler('forma:open-plugins');ipcMain.handle('forma:open-plugins',()=>{globalThis.pluginNavigations++;return{};});});await page.locator('#pluginButton').click();await page.locator('#extensionsInfo').waitFor();assert.equal(await app.evaluate(()=>globalThis.pluginNavigations),0);assert.match(await page.locator('#extensionsInfo').innerText(),/没有面向普通用户的插件安装器/);await page.locator('#extensionDeveloperLink').click();assert.equal(await app.evaluate(()=>globalThis.pluginNavigations),1);await page.locator('#closeExtensions').click();
await page.locator('#adviceWatchButton').click();assert.match(await page.locator('#adviceWatchDialog').innerText(),/支持离线/);await page.keyboard.press('Escape');
await page.locator('#budgetButton').click();const before=await page.evaluate(async()=>{const b=await window.forma.bootstrap();return window.forma.budgetGet(b.state.activeTaskId);});await page.locator('[data-budget-preset="8000"]').click();assert.equal(await page.locator('#budgetTotal').inputValue(),'8000');const unsaved=await page.evaluate(async()=>{const b=await window.forma.bootstrap();return window.forma.budgetGet(b.state.activeTaskId);});assert.equal(unsaved.total,before.total);await page.locator('#saveBudget').click();await page.waitForFunction(()=>document.querySelector('#budgetLive').textContent.includes('8,000'));await page.screenshot({path:path.join(evidence,'budget.png')});await (await import('node:fs/promises')).writeFile(path.join(evidence,'result.json'),JSON.stringify({passed:true,evidence,localStorageExplained:true,accountAndDemoDiscoverable:true,extensionsRequireDeliberateNavigation:true,adviceExample:true,budgetPresetRequiresSave:true}));}finally{await app.close();}
